import type { BarProgressProps } from "./bar-progress.types";

import { forwardRef } from "react";
import * as ProgressLoader from "@radix-ui/react-progress";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { BarProgressClasses, StyledBarProgress } from "./bar-progress.styles";

const BarProgress = forwardRef(
  (
    { className, variant = "default", max = 100, value, ...props }: BarProgressProps,
    ref: React.ForwardedRef<null>,
  ) => {
    const theme = useTheme();
    const isValueDefined = value != null;
    const rootClasses = clsx(BarProgressClasses.root, className);

    // For bar progress
    const barOffset = 100 - ((value ?? 0) / max) * 100;

    return (
      <StyledBarProgress
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
        aria-label={undefined}
      >
        <ProgressLoader.Root
          aria-label={props["aria-label"]}
          className={BarProgressClasses.track}
          max={max}
          value={value}
        >
          <ProgressLoader.Indicator
            className={clsx({
              [BarProgressClasses.indicatorIndeterminate]: !isValueDefined,
              [BarProgressClasses.indicatorDeterminate]: isValueDefined,
            })}
            style={isValueDefined ? { transform: `translateX(-${barOffset}%)` } : undefined}
          />
        </ProgressLoader.Root>
      </StyledBarProgress>
    );
  },
);

BarProgress.displayName = "BarProgress";

export default BarProgress;
